<script lang="ts">import {base} from '$app/paths';import type {Snippet} from 'svelte';import Frame from './CommunityFrame.svelte';import {channels,formatDate} from '$lib/community/channels';let {item,children}=$props<{item:any,children:Snippet}>();let info=$derived(channels.find(c=>c.id===item.channel)!);</script>
<svelte:head><title>{item.title} · FedRAMP Community</title></svelte:head>
<Frame><article class="item-detail"><header class="issue-opening"><a href={base+'/community/'+item.channel+'/'}>← {info.name}</a><h1>{item.title}</h1><p class="edition-date">{formatDate(item.date)} · {item.status}</p><p class="opening-deck">{item.summary}</p><a class="edition-link" href={item.source}>Read the original source ↗</a></header><div class="article-body">{@render children()}</div>{#if item.links.length}<nav class="resource-links" aria-label="Related source links">{#each item.links as l (l.url)}<a href={l.url}>{l.label} ↗</a>{/each}</nav>{/if}{#if item.comments?.length}<section class="thread-comments"><h2>Follow the comments</h2><p>Direct links include the surrounding exchange on GitHub. Dates below are when each comment was posted.</p><ol>{#each [...item.comments].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)) as c (c.id)}<li><a href={c.url}>{c.parentComment?'Reply':'Comment'} by @{c.author}</a><time datetime={c.createdAt}>{formatDate(c.createdAt)}</time></li>{/each}</ol></section>{/if}<p class="source-note">Saved source material for a design prototype. Discussion, guidance and proposals do not replace the published rules. Follow the original source for current context.</p></article></Frame>
